/** Worker entry: OpenNext's handler plus our Durable Object classes — the
 * per-account SyncJournal below, and Auth (durable-auth).
 * (wrangler `main` points here; OpenNext output is re-exported.) */

// Generated by `opennextjs-cloudflare build`; this file is excluded from
// tsconfig (wrangler bundles it with esbuild). cloudflare-env.d.ts still pulls
// it in for its DO class types, and a clean checkout has no build output yet.
// eslint-disable-next-line @typescript-eslint/ban-ts-comment -- ts-expect-error would fail once built
// @ts-ignore -- absent until the first build
import handler from "./.open-next/worker.js";
import { SyncJournal as OpLog } from "durable-sync/server";
import { AuthDurableObject } from "durable-auth/server";

/** One instance per account (idFromName(userId)): the single-threaded
 * consistency point that orders that user's sync ops.
 *
 * The log is durable-sync's journal, a native Durable Object called over RPC
 * — `push`, `pull`, `opsByKind` — from the API routes. What a `deleteWorkout`
 * op deleted is ours to interpret (src/server/tombstones.ts); the journal
 * never reads payloads, which is what keeps it a primitive.
 *
 * The class name is unchanged, so the existing Durable Object and its
 * migration tag carry straight over, and the SQL schema is the same, so the
 * live journal survives with no migration.
 */
export class SyncJournal extends OpLog {}

/** Accounts, passkeys and sessions (durable-auth). The class name is the one
 * the live Durable Object was created under, so its data carries over; the
 * library upgrades the schema in place on first use. */
export class Auth extends AuthDurableObject {}

export default handler;
